//! Integration tests over real files in tests/fixtures (generated by scripts/make_samples.py).

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::sync::atomic::AtomicBool;
use std::sync::{Arc, Mutex};
use vaultquery_lib::engine::{kind_of, ext_of, run, scan_file, Ctx, Hit, SearchEvent, SearchOpts};

const NEEDLE: &str = "VQ-NEEDLE-4242";
const IMEI: &str = "356938035643809";

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures")
}

fn all_kinds() -> Vec<String> {
    ["text", "spreadsheet", "document", "pdf", "archive"].map(String::from).to_vec()
}

fn opts(query: &str) -> SearchOpts {
    SearchOpts {
        root: fixtures().to_string_lossy().into_owned(),
        query: query.into(),
        kinds: all_kinds(),
        max_hits_per_file: 50,
        max_file_mb: 50,
        ..Default::default()
    }
}

fn hits_in(file: &str, query: &str) -> Vec<Hit> {
    let path = fixtures().join(file);
    let kind = kind_of(&ext_of(file)).unwrap();
    let ctx = Ctx::new(opts(query)).unwrap();
    let (hits, _) = scan_file(&path, kind, &ctx).unwrap_or_else(|e| panic!("{file}: {e}"));
    hits
}

fn locs(hits: &[Hit]) -> Vec<&str> {
    hits.iter().map(|h| h.loc.as_str()).collect()
}

#[test]
fn xlsx_reports_cell_and_header_fields() {
    let h = hits_in("sheet.xlsx", NEEDLE);
    assert_eq!(locs(&h), ["Data ! E5"], "title row + blank row + header => data row 2 is Excel row 5");
    let f = h[0].fields.as_ref().expect("header detected below the title row");
    let get = |n: &str| f.iter().find(|x| x.name == n).map(|x| x.value.as_str());
    assert_eq!(get("IMEI"), Some(IMEI), "numeric IMEI is printed without exponent");
    assert_eq!(get("Unit"), Some("DT-102"));
    assert!(f.iter().any(|x| x.name == "Note" && x.hit));
}

#[test]
fn xlsx_finds_numbers_stored_as_numbers() {
    assert_eq!(locs(&hits_in("sheet.xlsx", IMEI)), ["Data ! B5"]);
}

#[test]
fn legacy_xls() {
    let h = hits_in("legacy.xls", IMEI);
    assert_eq!(locs(&h), ["Sheet1 ! B3"]);
    assert!(h[0].fields.as_ref().unwrap().iter().any(|f| f.name == "Site" && f.value == "PIT B"));
}

#[test]
fn csv_with_semicolons_has_fields() {
    let h = hits_in("data.csv", NEEDLE);
    assert_eq!(locs(&h), ["Line 3"]);
    let f = h[0].fields.as_ref().unwrap();
    assert!(f.iter().any(|f| f.name == "Unit" && f.value == "DT-102"));
    assert!(f.iter().any(|f| f.name == "Note" && f.hit));
}

#[test]
fn utf16_text() {
    assert_eq!(locs(&hits_in("utf16.txt", NEEDLE)), ["Line 2"]);
}

#[test]
fn docx_paragraph() {
    let h = hits_in("doc.docx", IMEI);
    assert_eq!(h.len(), 1);
    assert!(h[0].loc.starts_with("Paragraph "), "{}", h[0].loc);
    assert_eq!(h[0].post, " installed.");
}

#[test]
fn pptx_slide() {
    assert_eq!(locs(&hits_in("deck.pptx", NEEDLE)), ["Slide 2"]);
}

#[test]
fn pdf_page() {
    assert_eq!(locs(&hits_in("report.pdf", NEEDLE)), ["Page 2"]);
}

#[test]
fn inside_zip() {
    let h = hits_in("archive.zip", NEEDLE);
    assert_eq!(locs(&h), ["inner/nested.xlsx › Sheet ! B2"]);
    let h = hits_in("archive.zip", IMEI);
    assert_eq!(locs(&h), ["inner/logs.csv › Line 2"]);
}

#[test]
fn case_and_whole_word() {
    assert_eq!(hits_in("utf16.txt", "vq-needle-4242").len(), 1, "case-insensitive by default");
    let mut o = opts("vq-needle-4242");
    o.case_sensitive = true;
    let ctx = Ctx::new(o).unwrap();
    let (h, _) = scan_file(&fixtures().join("utf16.txt"), "text", &ctx).unwrap();
    assert!(h.is_empty());
}

#[test]
fn corrupt_file_is_an_error_not_a_panic() {
    let ctx = Ctx::new(opts(NEEDLE)).unwrap();
    assert!(scan_file(&fixtures().join("corrupt.xlsx"), "spreadsheet", &ctx).is_err());
}

// ---------------------------------------------------------------- end-to-end through run()

fn run_collect(o: SearchOpts) -> (Vec<(String, Vec<Hit>)>, Vec<(String, String)>) {
    let matches = Mutex::new(Vec::new());
    let unreadable = Mutex::new(Vec::new());
    run(o, Arc::new(AtomicBool::new(false)), &|ev| match ev {
        SearchEvent::Match { file } => matches.lock().unwrap().push((file.name, file.hits)),
        SearchEvent::Unreadable { path, reason } => unreadable.lock().unwrap().push((path, reason)),
        SearchEvent::Failed { message } => panic!("{message}"),
        _ => {}
    });
    (matches.into_inner().unwrap(), unreadable.into_inner().unwrap())
}

#[test]
fn every_format_found_end_to_end() {
    let (m, bad) = run_collect(opts(NEEDLE));
    let names: HashSet<&str> = m.iter().map(|(n, _)| n.as_str()).collect();
    for f in ["sheet.xlsx", "legacy.xls", "data.csv", "utf16.txt", "doc.docx", "deck.pptx", "report.pdf", "archive.zip"] {
        assert!(names.contains(f), "{f} missing from {names:?}");
    }
    assert_eq!(bad.len(), 1, "only corrupt.xlsx is unreadable: {bad:?}");
    assert!(bad[0].0.ends_with("corrupt.xlsx"));
}

#[test]
fn bulk_mode_tags_terms() {
    let mut o = opts("");
    o.terms = vec![IMEI.into(), "DT-103".into(), "NOT-ANYWHERE-999".into()];
    let (m, _) = run_collect(o);
    let found: HashSet<String> = m.iter().flat_map(|(_, h)| h.iter().filter_map(|h| h.term.clone())).collect();
    assert!(found.contains(IMEI));
    assert!(found.contains("DT-103"));
    assert!(!found.contains("NOT-ANYWHERE-999"));
}

#[test]
fn name_filters() {
    let mut o = opts(NEEDLE);
    o.name_include = vec!["*.xls*".into()];
    o.name_exclude = vec!["legacy".into()];
    let (m, _) = run_collect(o);
    let names: Vec<&str> = m.iter().map(|(n, _)| n.as_str()).collect();
    assert_eq!(names, ["sheet.xlsx"]);
}

#[test]
fn date_filter_excludes_old_files() {
    let mut o = opts(NEEDLE);
    o.modified_after = Some(u64::MAX / 2); // far future: nothing qualifies
    let (m, _) = run_collect(o);
    assert!(m.is_empty());
}
